import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { X, Plus, Trash2, Calendar } from 'lucide-react';
import { validateCollaboration } from '../validation/skillValidation';

const CollaborationForm = ({ collaboration, onSubmit, onCancel, loading = false }) => {
  const [errors, setErrors] = useState({});
  const [requiredSkills, setRequiredSkills] = useState(
    collaboration?.requiredSkills || [{ name: '', level: 'intermediate' }]
  );
  
  const {
    register,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm({
    defaultValues: collaboration || {
      title: '',
      description: '',
      deadline: '',
    },
  });

  const skillLevels = ['beginner', 'intermediate', 'advanced', 'expert'];

  const addSkill = () => {
    setRequiredSkills([...requiredSkills, { name: '', level: 'intermediate' }]);
  };

  const removeSkill = (index) => {
    const newSkills = requiredSkills.filter((_, i) => i !== index);
    setRequiredSkills(newSkills);
  };

  const updateSkill = (index, field, value) => {
    const newSkills = [...requiredSkills];
    newSkills[index][field] = value;
    setRequiredSkills(newSkills);
  };

  const onFormSubmit = async (data) => {
    const formData = {
      ...data,
      requiredSkills: requiredSkills.filter(skill => skill.name.trim()),
    };

    const validationErrors = validateCollaboration(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    
    setErrors({});
    await onSubmit(formData);
  };

  const handleInputChange = (field) => {
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: undefined }));
    }
  };

  // Set minimum date to today
  const today = new Date().toISOString().split('T')[0];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#3D3D3D]/45 p-4 backdrop-blur-sm">
      <div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-[28px] border border-[#eadfce] bg-[#fffaf4] shadow-[0_30px_80px_rgba(61,61,61,0.18)]">
        <div className="flex items-center justify-between border-b border-[#eadfce] bg-[linear-gradient(135deg,rgba(224,122,95,0.10),rgba(242,201,76,0.14))] p-6">
          <h2 className="text-xl font-semibold text-[#3D3D3D]">
            {collaboration ? 'Edit Collaboration Request' : 'Create Collaboration Request'}
          </h2>
          <button
            onClick={onCancel}
            className="rounded-full p-2 text-[#85786c] transition-colors hover:bg-white/70 hover:text-[#3D3D3D]"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit(onFormSubmit)} className="p-6 space-y-6">
          {/* Title */}
          <div>
            <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-1">
              Project Title *
            </label>
            <input
              {...register('title')}
              type="text"
              onChange={() => handleInputChange('title')}
              className={`form-input block w-full px-3 py-2 border rounded-md focus:ring-primary-500 focus:border-primary-500 ${
                errors.title ? 'border-red-300' : 'border-gray-300'
              }`}
              placeholder="Enter a descriptive title for your collaboration"
            />
            {errors.title && (
              <p className="mt-1 text-sm text-red-600">{errors.title}</p>
            )}
          </div>

          {/* Description */}
          <div>
            <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-1">
              Project Description *
            </label>
            <textarea
              {...register('description')}
              onChange={() => handleInputChange('description')}
              rows={4}
              className={`form-input block w-full px-3 py-2 border rounded-md focus:ring-primary-500 focus:border-primary-500 ${
                errors.description ? 'border-red-300' : 'border-gray-300'
              }`}
              placeholder="Describe your project, goals, and what you're looking for in collaborators..."
            />
            {errors.description && (
              <p className="mt-1 text-sm text-red-600">{errors.description}</p>
            )}
            <p className="mt-1 text-xs text-gray-500">
              {1000 - (register('description').value?.length || 0)} characters remaining
            </p>
          </div>

          {/* Required Skills */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <label className="block text-sm font-medium text-gray-700">
                Required Skills *
              </label>
              <button
                type="button"
                onClick={addSkill}
                className="flex items-center rounded-full bg-[#d9ecf7] px-4 py-2 text-sm font-medium text-[#0b5f8f] transition-colors hover:bg-[#c9e2f1]"
              >
                <Plus className="h-4 w-4 mr-1" />
                Add Skill
              </button>
            </div>
            
            <div className="space-y-3">
              {requiredSkills.map((skill, index) => (
                <div key={index} className="flex items-center space-x-3 rounded-2xl border border-[#f0e1cf] bg-white/80 p-3">
                  <div className="flex-1">
                    <input
                      type="text"
                      placeholder="Skill name (e.g., React, Data Analysis)"
                      value={skill.name}
                      onChange={(e) => updateSkill(index, 'name', e.target.value)}
                      className="form-input w-full"
                    />
                  </div>
                  <select
                    value={skill.level}
                    onChange={(e) => updateSkill(index, 'level', e.target.value)}
                    className="form-input"
                  >
                    {skillLevels.map(level => (
                      <option key={level} value={level} className="capitalize">
                        {level}
                      </option>
                    ))}
                  </select>
                  {requiredSkills.length > 1 && (
                    <button
                      type="button"
                      onClick={() => removeSkill(index)}
                      className="rounded-full p-2 text-[#b85f47] transition-colors hover:bg-[#f6e3dc]"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}
                </div>
              ))}
            </div>
            
            {errors.requiredSkills && (
              <p className="mt-1 text-sm text-red-600">{errors.requiredSkills}</p>
            )}
          </div>

          {/* Deadline */}
          <div>
            <label htmlFor="deadline" className="block text-sm font-medium text-gray-700 mb-1">
              Deadline (Optional)
            </label>
            <div className="relative">
              <Calendar className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input
                {...register('deadline')}
                type="date"
                min={today}
                onChange={() => handleInputChange('deadline')}
                className={`form-input block w-full pl-10 pr-3 py-2 border rounded-md focus:ring-primary-500 focus:border-primary-500 ${
                  errors.deadline ? 'border-red-300' : 'border-gray-300'
                }`}
              />
            </div>
            {errors.deadline && (
              <p className="mt-1 text-sm text-red-600">{errors.deadline}</p>
            )}
            <p className="mt-1 text-xs text-gray-500">
              Set a deadline for your collaboration request
            </p>
          </div>

          <div className="flex justify-end space-x-3 pt-4">
            <button
              type="button"
              onClick={onCancel}
              disabled={isSubmitting || loading}
              className="rounded-full border border-[#d9cab6] bg-white px-5 py-2.5 text-sm font-medium text-[#5d544d] transition-colors hover:bg-[#fff7ed] focus:outline-none focus:ring-2 focus:ring-[#0077B6]/20 disabled:cursor-not-allowed disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting || loading}
              className="rounded-full border border-transparent bg-[#0077B6] px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-[#005f92] focus:outline-none focus:ring-2 focus:ring-[#0077B6]/20 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSubmitting || loading ? (
                <div className="flex items-center">
                  <div className="loading-spinner w-4 h-4 mr-2"></div>
                  {collaboration ? 'Updating...' : 'Creating...'}
                </div>
              ) : (
                collaboration ? 'Update Request' : 'Create Request'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CollaborationForm;
